using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class SouthBeachBays {
const string Dir="Assets/Scenes/Oasis/SouthBeach";static List<Vector2> coast;static float[] distances;static float length;static SouthBeachBays(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("SouthBeachBays.request"))return;try{File.Delete("SouthBeachBays.request");}catch(IOException){return;}Run();}
static Vector2 Parse(string s){var a=s.Split(',');return new Vector2(float.Parse(a[0],System.Globalization.CultureInfo.InvariantCulture),float.Parse(a[1],System.Globalization.CultureInfo.InvariantCulture));}
static float Wave(float s)=>11*Mathf.Sin(s/48)+4*Mathf.Sin(s/23+.8f);
static void Nearest(Vector2 p,out float s,out Vector2 normal,out float d){d=float.MaxValue;s=0;normal=Vector2.zero;for(int i=1;i<coast.Count;i++){var e=coast[i]-coast[i-1];float t=Mathf.Clamp01(Vector2.Dot(p-coast[i-1],e)/e.sqrMagnitude);var q=coast[i-1]+e*t;float dd=Vector2.Distance(p,q);if(dd<d){d=dd;s=Mathf.Lerp(distances[i-1],distances[i],t);normal=new Vector2(e.y,-e.x).normalized;}}}
static void Along(float s,out Vector2 point,out Vector2 normal){int i=1;while(i<distances.Length-1&&distances[i]<s)i++;var e=coast[i]-coast[i-1];point=Vector2.Lerp(coast[i-1],coast[i],Mathf.InverseLerp(distances[i-1],distances[i],s));normal=new Vector2(e.y,-e.x).normalized;}
struct Vert{public Vector3 p,n;public Vector2 uv;public static Vert Mid(Vert a,Vert b)=>new Vert{p=(a.p+b.p)*.5f,n=(a.n+b.n).normalized,uv=(a.uv+b.uv)*.5f};}
static List<Vert> output;static int changed;static Vector3 Bend(Vector3 p){Nearest(new Vector2(p.x,p.z),out float s,out var normal,out float d);float fade=1-Mathf.SmoothStep(0,1,Mathf.InverseLerp(2,43,d));float end=Mathf.SmoothStep(0,1,s/100)*Mathf.SmoothStep(0,1,(length-s)/100);float amount=Wave(s)*fade*end;if(Mathf.Abs(amount)>.01f)changed++;return p+new Vector3(normal.x*amount,0,normal.y*amount);}
static void Tri(Vert a,Vert b,Vert c,int depth){var mid=(a.p+b.p+c.p)/3;Nearest(new Vector2(mid.x,mid.z),out float s,out var n,out float d);float ab=(a.p-b.p).sqrMagnitude,bc=(b.p-c.p).sqrMagnitude,ca=(c.p-a.p).sqrMagnitude;if(depth<7&&d<60&&s>0&&s<length&&Mathf.Max(ab,Mathf.Max(bc,ca))>144){if(ab>=bc&&ab>=ca){var m=Vert.Mid(a,b);Tri(a,m,c,depth+1);Tri(m,b,c,depth+1);}else if(bc>=ca){var m=Vert.Mid(b,c);Tri(a,b,m,depth+1);Tri(a,m,c,depth+1);}else{var m=Vert.Mid(c,a);Tri(a,b,m,depth+1);Tri(m,b,c,depth+1);}return;}foreach(var v0 in new[]{a,b,c}){var v=v0;v.p=Bend(v.p);output.Add(v);}}
static Material Mat(string name,Color color){string path=Dir+"/"+name+".mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(!mat){mat=new Material(Shader.Find("Universal Render Pipeline/Lit"));AssetDatabase.CreateAsset(mat,path);}mat.SetColor("_BaseColor",color);mat.SetFloat("_Smoothness",.12f);mat.enableInstancing=true;EditorUtility.SetDirty(mat);return mat;}
static void Box(GameObject root,Vector3 p,Vector3 scale,Material mat,bool collider=false){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name="Pier structure";g.transform.SetParent(root.transform,false);g.transform.localPosition=p;g.transform.localScale=scale;g.GetComponent<Renderer>().sharedMaterial=mat;if(!collider)UnityEngine.Object.DestroyImmediate(g.GetComponent<Collider>());}
static void Combine(GameObject root,Material mat,string path){var filters=root.GetComponentsInChildren<MeshFilter>().Where(f=>f.GetComponent<Renderer>().sharedMaterial==mat).ToArray();var combos=filters.Select(f=>new CombineInstance{mesh=f.sharedMesh,transform=root.transform.worldToLocalMatrix*f.transform.localToWorldMatrix}).ToArray();var mesh=new Mesh{name=root.name+" mobile combined"};mesh.CombineMeshes(combos,true,true);AssetDatabase.CreateAsset(mesh,path);var g=new GameObject(mat.name);g.transform.SetParent(root.transform,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;foreach(var f in filters){var col=f.GetComponent<BoxCollider>();if(col){var c=g.AddComponent<BoxCollider>();c.center=f.transform.localPosition;c.size=f.transform.localScale;}UnityEngine.Object.DestroyImmediate(f.gameObject);}}
static void Run(){try{Directory.CreateDirectory(Dir);Directory.CreateDirectory("FinalEnvironmentRoadBackup/SouthBeachBefore");var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");if(!File.Exists("FinalEnvironmentRoadBackup/SouthBeachBefore/Scene.unity"))File.Copy(scene.path,"FinalEnvironmentRoadBackup/SouthBeachBefore/Scene.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var shore=root.GetComponentsInChildren<MeshFilter>().Single(f=>f.name=="Outer_MEsh");if(scene.GetRootGameObjects().Any(g=>g.name=="South Beach Bays and Docking Piers"))throw new Exception("Beach already built; stop to avoid duplicate piers");var hull=File.ReadAllLines("FinalEnvironmentRoadReview/BeachSouthHull.csv").Select(Parse).ToList();int start=hull.FindIndex(v=>v.x<0&&v.y>590);coast=new List<Vector2>{new Vector2(0,596.75f)};for(int i=start;i<hull.Count;i++)coast.Add(hull[i]);for(int i=0;i<start&&hull[i].x<0;i++)coast.Add(hull[i]);coast.Add(new Vector2(0,-783.12f));distances=new float[coast.Count];for(int i=1;i<coast.Count;i++)distances[i]=distances[i-1]+Vector2.Distance(coast[i],coast[i-1]);length=distances.Last();
var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{shore.sharedMesh});var p=(Vector3[])data.GetType().GetField("p").GetValue(data);var normals=(Vector3[])data.GetType().GetField("normal").GetValue(data);var uv=((Vector2[][])data.GetType().GetField("uv").GetValue(data))[0];var ids=(int[])data.GetType().GetField("ids").GetValue(data);output=new List<Vert>();for(int i=0;i<ids.Length;i+=3){var a=new Vert[3];for(int k=0;k<3;k++){int id=ids[i+k];a[k]=new Vert{p=shore.transform.TransformPoint(p[id]),n=shore.transform.TransformDirection(normals[id]),uv=uv[id]};}Tri(a[0],a[1],a[2],0);}var mesh=new Mesh{name="South coast gentle bays; other coast retained",indexFormat=UnityEngine.Rendering.IndexFormat.UInt32};mesh.SetVertices(output.Select(v=>shore.transform.InverseTransformPoint(v.p)).ToList());mesh.SetNormals(output.Select(v=>shore.transform.InverseTransformDirection(v.n)).ToList());mesh.SetUVs(0,output.Select(v=>v.uv).ToList());mesh.SetTriangles(Enumerable.Range(0,output.Count).ToArray(),0);mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,Dir+"/Wavy Southern Shore.asset");string source=AssetDatabase.GetAssetPath(shore.sharedMesh);File.WriteAllText("FinalEnvironmentRoadBackup/SouthBeachBefore/Original Shore Asset.txt",source);var roadPrefab=PrefabUtility.LoadPrefabContents("Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");roadPrefab.transform.Find(AnimationUtility.CalculateTransformPath(shore.transform,root.transform)).GetComponent<MeshFilter>().sharedMesh=mesh;PrefabUtility.SaveAsPrefabAsset(roadPrefab,"Assets/Scenes/Oasis/FinalEnvironmentRoads/Final Roads.prefab");PrefabUtility.UnloadPrefabContents(roadPrefab);shore.sharedMesh=mesh;PrefabUtility.RecordPrefabInstancePropertyModifications(shore);
var beach=new GameObject("South Beach Bays and Docking Piers");var wood=Mat("Shared pier weathered wood",new Color(.34f,.25f,.15f));var stone=Mat("Shared pier foundation",new Color(.29f,.31f,.29f));int piers=6;for(int k=0;k<piers;k++){float s=180+(length-360)*k/(piers-1);Along(s,out var point,out var normal);point+=normal*Wave(s);var pier=new GameObject("Small docking pier "+(k+1));pier.transform.SetParent(beach.transform,false);pier.transform.position=new Vector3(point.x,28.05f,point.y);pier.transform.rotation=Quaternion.LookRotation(new Vector3(normal.x,0,normal.y));float span=52+(k%3)*7;Box(pier,new Vector3(0,0,span*.5f-4),new Vector3(4.8f,.45f,span+8),wood,true);Box(pier,new Vector3(0,.04f,span-3),new Vector3(9,.5f,6),wood,true);for(float z=3;z<span;z+=9)foreach(float x in new[]{-1.9f,1.9f}){Box(pier,new Vector3(x,-4.9f,z),new Vector3(.45f,10,.45f),stone);Box(pier,new Vector3(x,.53f,z),new Vector3(.22f,.65f,.22f),wood);}Combine(pier,wood,Dir+"/Pier "+(k+1)+" Deck.asset");Combine(pier,stone,Dir+"/Pier "+(k+1)+" Pilings.asset");PrefabUtility.SaveAsPrefabAssetAndConnect(pier,Dir+"/Docking Pier "+(k+1)+".prefab",InteractionMode.AutomatedAction);}PrefabUtility.SaveAsPrefabAssetAndConnect(beach,Dir+"/South Beach Piers.prefab",InteractionMode.AutomatedAction);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic);capture.Invoke(null,new object[]{scene,new Vector3(-1250,1050,-120),new Vector3(-150,25,-90),"Wavy-Beach-and-Docking-Piers-Overview"});capture.Invoke(null,new object[]{scene,new Vector3(-700,145,150),new Vector3(-520,26,120),"Wavy-Beach-Pier-Closeup"});File.WriteAllText("FinalEnvironmentRoadReview/SouthBeachReport.txt","SUCCESS marked southern island U coast length="+length+"m; changed shore samples="+changed+"; gentle wave amplitude<=15m with 100m endpoint fades and 43m apron blend; new shoreline triangles="+mesh.triangles.Length/3+"; docking piers="+piers+"; 2 batched renderers per pier, shared instanced materials, simple deck colliders, pier prefabs; existing roads/buildings/mountains retained; original shore asset and scene backup retained.");}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/SouthBeachReport.txt","FAILED "+e);Debug.LogException(e);}}
}
